// Buffer carries only what abstract commands cannot reach (the V dump
// sweep), so a drain of a non-V state must issue NO PB execution.
TEST_CASE("drain reads GPRs and FPRs via abstract reads only -- no PB "
          "store-sweep, even when the V region leaves scratch room")
{
  RecordingBus bus;
  bus.dmstatus_value   = kDmstatusHaltedAndAcked;
  bus.abstractcs_value = 8u << 24;  // progbufsize = 8
  for (uint16_t i = 1; i < 32; ++i)
    bus.regfile[hybrid::regno_gpr(i)] = 0xC0000000ULL + i;
  for (uint16_t i = 0; i < 32; ++i)
    bus.regfile[hybrid::regno_fpr(i)] = 0xD0000000ULL + i;
  bus.regfile[hybrid::regno_csr(RD::kCsrFcsr)] = 0x45;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP;
  input.priv    = 3;
  input.vlenb   = 64;

  hybrid::StateDrain drain(bus, kScratch);
  const auto state = drain.drain_with_passthrough(input);

  // Every GPR/FPR value arrives via its abstract read...
  for (int i = 1; i < 32; ++i)
    CHECK(state.gpr[i] == 0xC0000000ULL + uint64_t(i));
  for (int i = 0; i < 32; ++i)
    CHECK(state.fpr[i] == 0xD0000000ULL + uint64_t(i));
  CHECK(state.fcsr == 0x45u);

  // ...and no Program-Buffer execution occurred at all -- with no V state
  // there is nothing the abstract command space cannot reach.
  for (const auto& op : bus.ops)
    CHECK_FALSE((op.kind == DmiOp::Kind::Write && op.reg == RD::kCommand
                 && op.value == hybrid::kExecProgbufCmd));
}

TEST_CASE("CSR drain is Abstract-Command-only: every Andes+M-ext CSR gets its "
          "own abstract read, never a Program-Buffer csrr+sd sweep")
{
  RecordingBus bus;
  bus.dmstatus_value   = kDmstatusHaltedAndAcked;
  bus.abstractcs_value = 8u << 24;  // progbufsize=8: a batch would fit here

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;
  input.priv    = 3;
....TAIL
    bus.regfile[hybrid::regno_csr(addrs[k])] = 0xC5000000ULL + k;

  hybrid::StateDrain drain(bus, kScratch);
  auto state = drain.drain_with_passthrough(input);

  // (a) every transported CSR's value landed in the state via its own
  //     abstract read.
  std::size_t k = 0;
  hybrid::for_each_transport_csr(state, hybrid::AndesCaps::all(),
    [&](uint16_t, uint64_t& field) {
      CHECK(field == 0xC5000000ULL + k);
      ++k;
    });

  // (b) no Program-Buffer execution occurred at all -- with no V state, the
  //     only possible PB user would have been a CSR sweep.
  for (const auto& op : bus.ops)
    CHECK_FALSE((op.kind == DmiOp::Kind::Write && op.reg == RD::kCommand
                 && op.value == hybrid::kExecProgbufCmd));
}

1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/andes_caps.hpp"
9	#include "hybrid/dmi_poll.hpp"
10	#include "hybrid/resume_driver.hpp"
11	#include "hybrid/state_abi.h"
12	#include "hybrid/v_regfile_xfer.hpp"
13	
14	#include <cstdint>
