17	{
18	
19	class StateDrain
20	{
21	public:
22	  using RD = ResumeDriver;
23	
24	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
25	  // the mmap's top page, v_scratch_gpa(ram_base, ram_size)). Defaults to the
26	  // unset sentinel; only the V dump sweep consults it, and it throws there if
27	  // a V drain is reached with the GPA unset (no silent dump to a bogus
28	  // address). The simulator passes the real value from platform.main_memory.
29	  // caps: which Andes custom CSRs the TARGET core implements (from its
30	  // config.inc, supplied by the sim binary). Defaults to all() so existing
31	  // call sites are unchanged. Gates the Andes re-read below: reading an
32	  // unimplemented CSR can stall the DM, same as restoring one.
33	  explicit StateDrain(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
34	                      AndesCaps caps = AndesCaps::all())
35	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
36	  {}
37	
38	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
39	  // drain_with_passthrough when the QEMU 1 snapshot is available.
40	  auto drain() -> hybrid_state_v1
41	  {
42	    hybrid_state_v1 state{};
43	    state.magic   = HYBRID_STATE_MAGIC;
44	    state.version = HYBRID_STATE_VERSION;
45	    state.flags   = HYBRID_FLAG_RV64;
46	    halt_and_capture_pc_priv(state);
47	
48	    for (uint16_t i = 1; i < 32; ++i)
49	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
50	
51	    return state;
52	  }
53	
54	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
55	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
56	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
57	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set, also
58	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
59	  // and vreg remain pass-through (read-only / too large for DM).
60	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
61	  // contribution would otherwise be discarded as the passthrough preserves
62	  // QEMU1's pre-handoff value.
63	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
64	  {
65	    auto state = input;
66	    halt_and_capture_pc_priv(state);  // L6: pc + privilege at the exit halt
67	
68	    // GPRs/FPRs: one abstract register read each. Abstract-only by design,
69	    // like the resume side -- the Program Buffer is reserved for state the
70	    // abstract command space cannot reach (the V regfile, vtype/vl).
71	    for (uint16_t i = 1; i < 32; ++i)
72	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
73	
74	    if (input.flags & HYBRID_FLAG_FP) {
75	      for (uint16_t i = 0; i < 32; ++i)
76	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
77	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
78	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
79	    }
80	
81	    if (input.flags & HYBRID_FLAG_V) {
82	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
83	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
84	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
85	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
86	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
87	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
88	    }
89	
90	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
91	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
92	    // dropped and the stale QEMU1 value passes through into the drained state.
93	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
94	
95	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
96	    // restores them), so re-read them -- an in-ROI write must reach the drained
97	    // state instead of the stale QEMU1 passthrough value.
98	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
99	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
100	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
101	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
102	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
103	
104	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
105	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
106	
107	    // Andes V5 + M-ext CSR block (v3/v4): re-read the transported CSRs so an
108	    // in-ROI write reaches the drained state instead of the stale QEMU1
109	    // passthrough (same round-trip as mscratch). One caps-gated abstract read
110	    // per CSR. See drain_andes_m_ext.
111	    drain_andes_m_ext(state);
112	
113	    // V data regfile: dump v0..v31 to the shared scratch region via the
114	    // Program Buffer LAST -- after every architectural read above -- so the
115	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
116	    // cannot corrupt the values already captured. The simulator's
117	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
118	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
119	    if (input.flags & HYBRID_FLAG_V)
120	      dump_v_to_scratch(input.vlenb);
121	
122	    return state;
123	  }
124	
125	private:
126	  // Halt the hart and capture the two control fields every drain path needs:
127	  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
128	  // blocks are filled by the caller, so drain() and drain_with_passthrough
129	  // share one halt + prologue. dmactive must transition 0->1 in its own write
130	  // before haltreq is honored (RISC-V Debug Spec), then wait for allhalted.
131	  void halt_and_capture_pc_priv(hybrid_state_v1& state)
132	  {
133	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
134	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
135	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
136	                   "StateDrain halt");
137	
138	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
139	                                  "StateDrain DCSR") & 0x3u;
140	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
141	  }
142	
143	  // Andes V5 + M-ext CSR drain: one caps-gated abstract read per CSR into
144	  // state. Abstract-only by design, same caps gate + canonical order as the
145	  // ResumeDriver restore.
146	  void drain_andes_m_ext(hybrid_state_v1& state)
147	  {
148	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
149	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
150	    if (!andes && !mext) return;
151	
152	    if (andes) {
153	#define X(field, addr, name) \
154	  if (caps_.supports_csr(addr)) \
155	    state.andes.field = read_register_64(bus_, regno_csr(addr));
156	      HYBRID_ANDES_CSR_LIST(X)
157	#undef X
158	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
159	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
160	          state.andes.pmacfg[i] =
161	            read_register_64(bus_, regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
162	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
163	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
164	          state.andes.pmaaddr[i] =
165	            read_register_64(bus_, regno_csr(HYBRID_PMA_ADDR0_CSR + i));
166	    }
167	    if (mext) {
168	#define X(field, addr, name) \
169	  if (caps_.supports_csr(addr)) \
170	    state.m_ext.field = read_register_64(bus_, regno_csr(addr));
171	      HYBRID_M_EXT_CSR_LIST(X)
172	#undef X
173	    }
174	  }
175	
176	  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
177	  // L26: guards on the configured scratch GPA so a V drain never stores to a
178	  // bogus address (mirror of ResumeDriver's reload-sweep guard).
179	  void dump_v_to_scratch(uint64_t vlenb)
180	  {
181	    if (scratch_gpa_ == kVScratchGpaUnset)
182	      throw std::runtime_error(
183	        "StateDrain: V state present but scratch GPA unset");
184	    pb_v_data_sweep(bus_, scratch_gpa_, vlenb, /*load=*/false);
185	  }
186	
187	  DmiBus& bus_;
188	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
189	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
190	};
