  // Caller invariant: the CPU must already be out of reset.
  void apply_resume_from_qemu(const std::string& path)
  {
    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
      bus{platform.dmi, platform.clk.period()};
    hybrid_input_state_ = hybrid::load_state(path);
    // Stage V-register bytes into the fixed scratch region of RAM BEFORE
    // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
    // this region to repopulate v0..v31, so the bytes must be in place first.
    // Best-effort: mismatched RAM layouts throw, which is louder than silently
    // dropping V state.
    if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
      hybrid::stage_v_to_scratch(*hybrid_input_state_,
                                 platform.main_memory.data);
    }
    hybrid::ResumeDriver driver(bus, v_scratch_gpa(),
                                hybrid::andes_caps_from_config());
    driver.resume(*hybrid_input_state_);
  }

  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
  // committed PCs and on retire of the exit marker HINT (`slti x0, x0,
  // 0x5A1`) drains architectural state to `state_out_path` and returns
  // kExitHandoffToQemu.
  //
  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
  // mode) and the ELF scan is skipped: the binary need not contain the
  // marker HINTs. Marker mode and PC mode are mutually exclusive on a
  // single run -- callers pass exactly one form.
  void enable_hybrid_handoff(const std::string& elf_path,
                             const std::string& state_out_path,
                             std::optional<uint64_t> exit_pc = std::nullopt)
  {
    hybrid::CsrTrigger trigger;
    if (exit_pc) {
      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
    } else {
      auto elf = LIEF::ELF::Parser::parse(elf_path);
      if (!elf)
        throw std::runtime_error(
          "enable_hybrid_handoff: failed to parse " + elf_path);
      for (const auto& seg: elf->segments()) {
        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
        const auto content = seg.content();
        const std::span<const uint8_t> bytes{content.data(), content.size()};
        trigger.scan_buffer(bytes, seg.virtual_address());
      }
    }

    hybrid_dmi_bus_ = std::make_unique<
      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
                            PLATFORM::dmi_data_width>>(platform.dmi,
                                                       platform.clk.period());
    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
                            v_scratch_gpa(), hybrid::andes_caps_from_config());
    if (hybrid_input_state_)
      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);

    hybrid_state_path_ = state_out_path;
  }

